import{z as B,x as i,o as n,c as C,q as o,j as l,D as t,d as r,s,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"Tenstorrent","description":"","frontmatter":{"title":"Tenstorrent","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/tenstorrent.md","filePath":"llm/tenstorrent.md","lastUpdated":1791063341000}'),p={name:"llm/tenstorrent.md"};function d(m,a,T,D,N,u){const E=i("Mermaid");return n(),C("div",null,[a[2]||(a[2]=o('<h1 id="tenstorrent" tabindex="-1">Tenstorrent <a class="header-anchor" href="#tenstorrent" aria-label="Permalink to &quot;Tenstorrent&quot;">​</a></h1><div class="epigraph"><p>很多小核、片上 SRAM、核间 NoC。看起来像加速器，编程起来更像给 mesh 写显式数据搬运，而不是写一份 CUDA kernel 就结束。</p><footer>—— Tenstorrent Tensix / 多核 mesh 的公开架构叙述</footer></div><p><a href="/llm/sambanova-dataflow">SambaNova</a> 把图收进可重配置通路。本课 Tenstorrent 走 <strong>多核 + NoC</strong>：Tensix 一类核带本地存储，靠片上网络搬张量。缺口是它与 GPU SIMT、TPU 脉动、数据流机的位置——更接近「分布式片上集群」，集体通信的思维又回来了，只是半径在芯片内。软件栈（TT-Metal 等公开层）成熟度是对比的主维。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GPU 用海量线程与缓存把数据搬运藏进硬件。Tenstorrent 把搬运交给程序员或编译器显式调度：谁持有哪块 SRAM、何时经 NoC 发给邻居。映射对了，带宽按片上计；映射错了，NoC 拥塞，核空等，症状类似机柜里的 All-to-All 热点，只是规模在毫米。</p><p>生态：CUDA 不直接跑。要内核库与图编译。LLM 能否吃满，取决于注意力与 MLP 的内核是否存在、以及多芯片如何接。问题是 <strong>把集群课的拓扑意识下放到片上</strong>，而不是找 NCCL 的替代 DLL。</p><p><span class="marginnote">术语翻译：NoC（Network-on-Chip，片上网络）就是把局域网做进芯片里——每个核像一台小电脑，带自己的 SRAM 小仓库，核与核之间靠路由器一跳跳传数据，而不是大家共用一个大内存池。谁在什么时候把哪块数据发给谁，要自己安排。</span></p><p><span class="marginnote">公开路线图与产品名变化快。本课只写稳定机制：多核、本地存储、NoC。不填写未发布芯片的 TFLOPS。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把层切成核上的 tile：类似手写 GPU 的 tiling，但缺少成熟的自动缓存。多芯片用板级或柜级互连扩展，再一层 \\(\\beta\\)。训练集体要在这层互连上实现，可能是自研库而不是 NCCL。与 <a href="/llm/amd-rocm-stack">AMD ROCm</a> 下一课不同：那里至少有 RCCL 去对齐 NCCL 语义。</p>',10)),(n(),l(A,null,{default:t(()=>[s(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CORE%5B%22Tensix%20%E6%A0%B8%20%2B%20SRAM%22%5D%20--%3E%20NOC%5B%22%E7%89%87%E4%B8%8A%20NoC%22%5D%0A%20%20NOC%20--%3E%20CORE2%5B%22%E9%82%BB%E5%B1%85%E6%A0%B8%22%5D%0A%20%20CHIP%5B%22%E8%8A%AF%E7%89%87%22%5D%20--%3E%20PKG%5B%22%E5%A4%9A%E8%8A%AF%E7%89%87%E4%BA%92%E8%BF%9E%22%5D%0A%20%20MAP%5B%22%E6%98%BE%E5%BC%8F%20tile%20%2F%20%E6%90%AC%E8%BF%90%22%5D%20--%3E%20NOC%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"服务与训练都能做，取决于软件。规划时把「内核是否存在」放在硬件规格之前。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"NoC 上的同步波与机柜集体同构：逻辑环是否嵌入物理邻居，决定 \\(\\alpha\\)。编译器或手写内核若按全局共享内存思维写，会把 NoC 打满。这是教学点：集群课的嵌入与轨对齐，在片上重复一遍。",-1)),a[6]||(a[6]=e("p",null,"与 Groq 比，运行时更灵活，确定性更弱。与 GPU 比，灵活性仍少（无线程抢占的成熟生态）。落在中间，优缺点都是「你要自己管搬运」。",-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},"RISC-V 外围或主机侧控制出现在公开叙述里时，只说明控制面，不说明矩阵乘屋顶线。比 FLOPS 仍要看矩阵单元与内存。")],-1)),a[8]||(a[8]=e("p",null,"同一块 tile，映射好坏直接决定吞吐走向：",-1)),(n(),l(A,null,{default:t(()=>[s(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%BE%85%E7%AE%97%E7%9A%84%20tile%22%5D%20--%3E%20M%7B%22%E6%98%A0%E5%B0%84%E5%88%B0%E5%93%AA%E4%B8%AA%E6%A0%B8%3F%22%7D%0A%20%20M%20--%3E%7C%22%E9%82%BB%E5%B1%85%E6%A0%B8%2C%20%E9%80%BB%E8%BE%91%E7%8E%AF%E8%B4%B4%E7%89%A9%E7%90%86%E7%8E%AF%22%7C%20G%5B%22NoC%20%E4%B8%80%E4%B8%A4%E8%B7%B3%E9%80%81%E8%BE%BE%22%5D%0A%20%20G%20--%3E%20G2%5B%22%E6%A0%B8%E6%BB%A1%E8%BD%BD%2C%20%E5%B8%A6%E5%AE%BD%E6%8C%89%E7%89%87%E4%B8%8A%E8%AE%A1%22%5D%0A%20%20M%20--%3E%7C%22%E8%BF%9C%E7%AB%AF%E6%A0%B8%2C%20%E7%8E%AF%E8%B7%A8%E5%8D%8A%E9%A2%97%E8%8A%AF%E7%89%87%22%7C%20B%5B%22%E5%A4%9A%E8%B7%B3%E4%BC%A0%E8%BE%93%2C%20%E9%80%94%E7%BB%8F%E6%A0%B8%E8%A2%AB%E5%8D%A0%E7%94%A8%22%5D%0A%20%20B%20--%3E%20B2%5B%22NoC%20%E6%8B%A5%E5%A1%9E%22%5D%0A%20%20B2%20--%3E%20B3%5B%22%E9%82%BB%E5%B1%85%E6%8E%92%E9%98%9F%2C%20%E8%AE%A1%E7%AE%97%E6%A0%B8%E7%A9%BA%E7%AD%89%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=o('<p><span class="marginnote">直觉类比：这像一栋没有中央仓库的办公楼——每个部门有自己的小储藏室，文件靠内部邮件传递。若 A 部门做完工件要穿过整层楼才到 B 部门，走廊（NoC）就会堵；把工序安排成相邻部门接力，走廊几乎不占用，楼里所有人都干着活。编译器或你手写的映射，就是在排这个部门接力表。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要用 CUDA 占用率公式。不要假设 RCCL / NCCL 测试能直接跑。不要把创始人新闻当规格。下一课 AMD 才是「有 CUDA 替代栈、有 RCCL」的近路。</p><p><span class="marginnote">常见误区：初学者容易拿 GPU 的「occupancy」「线程数」指标去诊断这类 mesh 芯片，结果一无所获——这里没有可抢占的线程池，瓶颈在 tile 映射与 NoC 流量。诊断要先问「数据每一步从谁的 SRAM 发到谁」，再看有没有链路被多对流量挤爆，最后才谈计算单元吃没吃满。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Tenstorrent：多核 + 本地 SRAM + NoC，数据搬运显式。</li><li>片上拓扑意识与集群集体同构，只是半径不同。</li><li>软件与内核库决定能否服务 LLM，先于 TFLOPS 表。</li><li>灵活性和确定性介于 GPU 与 LPU 之间。</li><li>出处：Tenstorrent 公开的 Tensix / mesh 架构叙述。</li></ul>',6))])}const f=B(p,[["render",d]]);export{P as __pageData,f as default};
